"""Writes games/hatchery-heist/src/shared/EnvArt.luau: every outdoor nature
model's meshes (name, centre, size, colour) from env.json, and the Roblox
asset ids of the uploaded models and images from assets.json.

    python3 tools/art/env/luau.py

Plain Python. env.json is written by build.py from the same build the
upload sends, so names and places always match the uploaded files. CI
re-runs this and fails if the committed file differs.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))


def num(v):
    v = round(v, 4)
    return str(int(v)) if v == int(v) else repr(v)


def vec(v):
    return '{ ' + ', '.join(num(x) for x in v) + ' }'


WIDTH = 110  # stylua.toml column_width; tabs count 4


def table_lines(depth, fields, trail=','):
    """A table laid out as StyLua would: one line when it fits, else one
    field a line (same rule as tools/art/blender/luau.py)."""
    one = '\t' * depth + '{ ' + ', '.join(fields) + ' }' + trail
    if len(one.expandtabs(4)) <= WIDTH:
        return [one]
    return ['\t' * depth + '{'] + ['\t' * (depth + 1) + f + ',' for f in fields] + ['\t' * depth + '}' + trail]


ROOT = os.path.normpath(os.path.join(HERE, '..', '..', '..'))
OUT = os.path.join(ROOT, 'games', 'hatchery-heist', 'src', 'shared', 'EnvArt.luau')
MANIFEST = os.path.join(HERE, 'env.json')
ASSETS = os.path.join(HERE, 'assets.json')
IMAGES = ['SkyboxBk', 'SkyboxDn', 'SkyboxFt', 'SkyboxLf', 'SkyboxRt', 'SkyboxUp', 'Grass']

HEADER = '''--!strict
-- GENERATED by tools/art/env/luau.py. Do not edit: change the art in
-- tools/art/env (nature.py, sky.py, grass.py), or the asset ids in
-- tools/art/env/assets.json, and run `python3 tools/art/env/luau.py`.
--
-- Hatchery Heist's outdoor nature as Blender meshes: trees, bushes, rocks,
-- flowers and grass, one MeshPart per colour. Studs, Y up, front -Z, the
-- base at Y = 0 centred on X and Z. `assetId` is the uploaded Model holding
-- MeshParts named after the meshes; 0 = not uploaded (the game then draws
-- its old box trees and leaves the small props out). `images` are the
-- uploaded skybox faces and grass tile; 0 = not uploaded (Roblox's own sky
-- and the plain Grass material).

export type Mesh = { name: string, center: { number }, size: { number }, color: string, glow: boolean? }
export type Model = {
	assetId: number,
	kind: string,
	size: { number },
	tris: number,
	meshes: { Mesh },
}
export type Images = {
	SkyboxBk: number,
	SkyboxDn: number,
	SkyboxFt: number,
	SkyboxLf: number,
	SkyboxRt: number,
	SkyboxUp: number,
	Grass: number,
}

local EnvArt: { models: { [string]: Model }, images: Images } = {
'''


def load(path, default):
    if not os.path.exists(path):
        return default
    with open(path) as f:
        return json.load(f)


def write():
    manifest = load(MANIFEST, {})
    assets = load(ASSETS, {'models': {}, 'images': {}})
    lines = [HEADER.rstrip('\n'), '\tmodels = {']
    for mid in sorted(manifest):
        m = manifest[mid]
        a = assets.get('models', {}).get(mid, {})
        aid = a.get('assetId', 0)
        assert isinstance(aid, int), f'assets.json: bad asset id for {mid}'
        lines.append(f'\t\t{mid} = {{')
        lines.append(f'\t\t\tassetId = {aid},')
        lines.append(f'\t\t\tkind = "{m["kind"]}",')
        lines.append(f'\t\t\tsize = {vec(m["size"])},')
        lines.append(f'\t\t\ttris = {m["tris"]},')
        lines.append('\t\t\tmeshes = {')
        for x in m['meshes']:
            fields = [f'name = "{x["name"]}"', f'center = {vec(x["center"])}', f'size = {vec(x["size"])}',
                      f'color = "{x["color"]}"']
            if x.get('glow'):
                fields.append('glow = true')
            lines += table_lines(4, fields)
        lines.append('\t\t\t},')
        lines.append('\t\t},')
    lines.append('\t},')
    lines.append('\timages = {')
    for k in IMAGES:
        entry = assets.get('images', {}).get(k, {})
        # only Image assets: a Decal id on a Sky face or Texture draws nothing
        aid = entry.get('assetId', 0) if entry.get('type') == 'Image' else 0
        assert isinstance(aid, int), f'assets.json: bad asset id for {k}'
        lines.append(f'\t\t{k} = {aid},')
    lines.append('\t},')
    lines.append('}')
    lines.append('')
    lines.append('return EnvArt')
    text = '\n'.join(lines) + '\n'
    with open(OUT, 'w') as f:
        f.write(text)
    print(f'wrote {os.path.relpath(OUT, ROOT)}: {len(manifest)} models, '
          f'{sum(1 for k in manifest if assets.get("models", {}).get(k))} uploaded')


if __name__ == '__main__':
    write()
